# Generates scripts/perf/driver/build/PerfDriver.xcodeproj: one iOS UI test bundle (XCUITest) that
# drives the installed sentry-demo app with real UIKit taps (scripts/perf/driver/PerfJourneyUITests.swift).
# The app's own Xcode project (ios/, generated by expo prebuild) is not touched: the test reaches the
# app by bundle id. Run with the Ruby and xcodeproj gem that ship with CocoaPods (scripts/perf/run.sh
# does this).
require "fileutils"
require "xcodeproj"

dir = File.expand_path("driver", __dir__)
out = File.join(dir, "build", "PerfDriver.xcodeproj")
FileUtils.rm_rf(out)
FileUtils.mkdir_p(File.dirname(out))

project = Xcodeproj::Project.new(out)
target = project.new_target(:ui_test_bundle, "PerfJourney", :ios, "17.0")
group = project.new_group("PerfJourney", dir)
ref = group.new_reference(File.join(dir, "PerfJourneyUITests.swift"))
target.add_file_references([ref])
target.build_configurations.each do |c|
  c.build_settings["PRODUCT_BUNDLE_IDENTIFIER"] = "dev.ouo.perfjourney"
  c.build_settings["GENERATE_INFOPLIST_FILE"] = "YES"
  c.build_settings["SWIFT_VERSION"] = "5.0"
  c.build_settings["CODE_SIGN_IDENTITY"] = "-"
  c.build_settings["CODE_SIGN_STYLE"] = "Manual"
  c.build_settings["TARGETED_DEVICE_FAMILY"] = "1"
end
project.save

scheme = Xcodeproj::XCScheme.new
scheme.add_test_target(target)
scheme.save_as(out, "PerfJourney", true)
puts out
